const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short --branch && git remote -v && git log -5 --oneline",max_output_tokens:3500}),
  tools.exec_command({cmd:"rg --files -g AGENTS.md -g composer.json -g composer.lock -g '.github/**' -g '*phpunit*' -g '*phpstan*' -g '*renovate*' -g '*Makefile*' -g 'Taskfile*' -g 'justfile' -g '.openai/hosting.json' -g '!vendor' -g '!node_modules' && cat /Users/ab/.agents/skills/find-docs/SKILL.md",max_output_tokens:7000})
]); for (let i=0;i<results.length;i++) text({i,...results[i]});
text(ALL_TOOLS.filter(x=>/search|github/.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,150)})).slice(0,100));

const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat AGENTS.md && rg --files --hidden .github && git log --oneline origin/main..main && git diff --stat origin/main..main",max_output_tokens:6500}),
  tools.exec_command({cmd:"gh run list --repo k-kinzal/php-ai-toolkit --branch main --limit 15 --json databaseId,name,headSha,status,conclusion,event,url,createdAt && gh pr list --repo k-kinzal/php-ai-toolkit --state open --limit 100 --json number,title,author,headRefName,headRefOid,baseRefName,mergeable,mergeStateStatus,statusCheckRollup,url",max_output_tokens:11000}),
  tools.exec_command({cmd:"git fetch origin",max_output_tokens:2000})
]);for (let i=0;i<results.length;i++) text({i,...results[i]});

const results= await Promise.allSettled([
 tools.exec_command({cmd:"gh run view 37406498250 --repo k-kinzal/php-ai-toolkit --json jobs && gh run view 37406498250 --repo k-kinzal/php-ai-toolkit --log-failed",max_output_tokens:9000}),
 tools.exec_command({cmd:"cat .github/workflows/ci.yml .github/workflows/mutation.yml && rg --files --hidden -g '!vendor' -g '!*lock*' -g '!node_modules' scripts bin tools && cat packages/guard-php/composer.json packages/docgen-php/composer.json && php -v && composer --version",max_output_tokens:10000}),
 tools.exec_command({cmd:"git status --porcelain=v1 | wc -l && git rev-list --left-right --count origin/main...main && git log -10 --format='%h %s' && rg -n 'infection|mutation|test|check|composer' README.md .github/workflows/mutation.yml",max_output_tokens:4000})
]);for(let i=0;i<results.length;i++)text({i,...results[i]});

const results= await Promise.allSettled([
 tools.exec_command({cmd:"gh run view 37406498250 --repo k-kinzal/php-ai-toolkit --log-failed | rg -n -C 9 'could not|Problem|requires|error|Error|missing|Install dependencies|platform|ext-'",max_output_tokens:4000}),
 tools.exec_command({cmd:"cat packages/guard-php/composer.json packages/docgen-php/composer.json && php -v && composer --version && command -v actionlint && rg --files --hidden -g 'AGENTS.md' -g '!vendor' -g '!node_modules' packages",max_output_tokens:6500}),
 tools.exec_command({cmd:"git diff --name-only --cached && rg -n 'dom|symfony/console|php\"|path|symlink' packages/*/composer.json && ls /opt/homebrew/opt/php*/bin/php && cat .github/workflows/docs.yml",max_output_tokens:4500})
]);for(let i=0;i<results.length;i++)text({i,...results[i]});

